-- PostgreSQL twin of migrations/0063_affiliates.sql, generated by scripts/sqlite_to_pg_migration.py

-- همکاری در فروش (affiliate), after Digikala and Basalam:
-- a referrer shares a personal link; the platform pays a base rate per category out of its own
-- commission; a seller may add an extra rate (paid from the seller's share). Earnings become
-- payable only after the buyer's withdrawal window/escrow ends and no return is open.
CREATE TABLE IF NOT EXISTS affiliates (
    id                BIGSERIAL PRIMARY KEY,
    user_id           INTEGER NOT NULL UNIQUE REFERENCES users(id),
    code              TEXT NOT NULL UNIQUE CHECK (length(code) BETWEEN 4 AND 24),
    status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
    sheba             TEXT,
    created_at        TEXT NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

-- Platform-paid base rate (share of line gross), by category; NULL category = default.
CREATE TABLE IF NOT EXISTS affiliate_rates (
    id           BIGSERIAL PRIMARY KEY,
    category_id  INTEGER REFERENCES categories(id) ON DELETE CASCADE,
    rate_bps     INTEGER NOT NULL CHECK (rate_bps BETWEEN 0 AND 2000),
    created_at   TEXT NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

INSERT INTO affiliate_rates (category_id, rate_bps) VALUES (NULL, 200);

-- Seller's optional extra rate for referrals of its own products.
ALTER TABLE suppliers ADD COLUMN affiliate_bonus_bps INTEGER NOT NULL DEFAULT 0
    CHECK (affiliate_bonus_bps BETWEEN 0 AND 2000);

-- Last referral a buyer arrived with (last click wins, 7 days).
CREATE TABLE IF NOT EXISTS affiliate_referrals (
    id            BIGSERIAL PRIMARY KEY,
    buyer_user_id INTEGER NOT NULL REFERENCES users(id),
    affiliate_id  INTEGER NOT NULL REFERENCES affiliates(id),
    landed_at     TEXT NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    expires_at    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_affiliate_referrals_buyer ON affiliate_referrals(buyer_user_id, id);

-- One earning per seller part of an order (fulfillment order).
CREATE TABLE IF NOT EXISTS affiliate_earnings (
    id                   BIGSERIAL PRIMARY KEY,
    affiliate_id         INTEGER NOT NULL REFERENCES affiliates(id),
    fulfillment_order_id INTEGER NOT NULL UNIQUE REFERENCES fulfillment_orders(id),
    order_id             INTEGER NOT NULL REFERENCES orders(id),
    gross_minor BIGINT NOT NULL CHECK (gross_minor >= 0),
    platform_paid_minor BIGINT NOT NULL CHECK (platform_paid_minor >= 0),
    seller_paid_minor BIGINT NOT NULL CHECK (seller_paid_minor >= 0),
    status               TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'reversed', 'paid')),
    available_at         TEXT NOT NULL,
    created_at           TEXT NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE INDEX IF NOT EXISTS ix_affiliate_earnings_affiliate ON affiliate_earnings(affiliate_id, status);
